mapper.select:
SELECT id, tenant_id, owner_id, session_id, agent_id, agent_role, event_type, event_key,
       role, content, structured_payload::text AS structured_payload, source_type,
       trust_level, source_message_id, sequence_no, created_at
FROM memory_event
WHERE tenant_id = #{tenantId}
  AND owner_id = #{ownerId}
  AND session_id = CAST(#{sessionId} AS uuid)
ORDER BY sequence_no ASC
LIMIT #{limit}
